import random
def find_kth_largest(nums, k):
    def qs(a, lo, hi, target):
        pivot = a[random.randint(lo, hi)]
        l, m, r = lo, lo, hi
        while m <= r:
            if a[m] > pivot: a[l], a[m] = a[m], a[l]; l += 1; m += 1
            elif a[m] < pivot: a[m], a[r] = a[r], a[m]; r -= 1
            else: m += 1
        if target < l: return qs(a, lo, l-1, target)
        if target > r: return qs(a, r+1, hi, target)
        return a[target]
    return qs(nums, 0, len(nums)-1, k-1)

import heapq
def find_maximized_capital(k, w, profits, capital):
    proj = sorted(zip(capital, profits))
    i = 0; avail = []
    for _ in range(k):
        while i < len(proj) and proj[i][0] <= w:
            heapq.heappush(avail, -proj[i][1]); i += 1
        if not avail: break
        w += -heapq.heappop(avail)
    return w

import heapq
class MedianFinder:
    def __init__(self):
        self.lo = []  # max-heap (neg)
        self.hi = []  # min-heap
    def addNum(self, x):
        heapq.heappush(self.lo, -x)
        heapq.heappush(self.hi, -heapq.heappop(self.lo))
        if len(self.hi) > len(self.lo):
            heapq.heappush(self.lo, -heapq.heappop(self.hi))
    def findMedian(self):
        if len(self.lo) > len(self.hi):
            return -self.lo[0]
        return (-self.lo[0] + self.hi[0]) / 2

class MedianFinder:
    def __init__(self): self.a = []
    def addNum(self, x): self.a.append(x)
    def findMedian(self):
        self.a.sort()
        n = len(self.a)
        return self.a[n//2] if n % 2 else (self.a[n//2-1] + self.a[n//2]) / 2
